{
  "title": "The Gilded Ruin Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A lone scout arrives at the ruined city gates.",
      "visual_description": "Crumbling stone archways draped in faded royal banners, dust swirling in the afternoon light.",
      "characters": ["scout"]
    },
    {
      "scene_number": 2,
      "caption": "The scout reports to the rescue party in a hollowed temple.",
      "visual_description": "Broken stained-glass window casting colored shards onto a makeshift camp with worried faces.",
      "characters": ["scout", "rescue_leader", "sorceress", "guard"]
    },
    {
      "scene_number": 3,
      "caption": "The party enters the main square, past frightened townspeople.",
      "visual_description": "Cobblestones littered with debris, families huddled in doorways, eyes darting toward armored patrols.",
      "characters": ["rescue_leader", "sorceress", "guard", "townspeople"]
    },
    {
      "scene_number": 4,
      "caption": "An armored patrol demands papers at a checkpoint.",
      "visual_description": "Soldiers in rusted plate armor holding pikes before a barricade of overturned carts.",
      "characters": ["guard", "armored_patrol_leader", "armored_patrol_soldier"]
    },
    {
      "scene_number": 5,
      "caption": "The sorceress distracts the patrol with a phantom wisp.",
      "visual_description": "Glowing blue light zigzagging between rooftops, guards turning and shouting.",
      "characters": ["sorceress", "armored_patrol_leader", "armored_patrol_soldier"]
    },
    {
      "scene_number": 6,
      "caption": "The party slips into a cursed tower’s shadowy entrance.",
      "visual_description": "Twisted iron door half-open, strange runes pulsing faintly on the stone frame.",
      "characters": ["rescue_leader", "sorceress", "guard"]
    },
    {
      "scene_number": 7,
      "caption": "Inside, illusions of treasure and feasts tempt the guard.",
      "visual_description": "Golden goblets and piled coins shimmering in torchlight, a ghostly banquet table.",
      "characters": ["guard", "rescue_leader", "sorceress"]
    },
    {
      "scene_number": 8,
      "caption": "The sorceress breaks the illusion with a counterspell.",
      "visual_description": "Rippling air like heat haze, the feast dissolving into bare stone walls.",
      "characters": ["sorceress", "guard", "rescue_leader"]
    },
    {
      "scene_number": 9,
      "caption": "They find a captive locked in a magical cage at the tower's heart.",
      "visual_description": "Bars of violet energy in a circular chamber, a haggard figure kneeling inside.",
      "characters": ["rescue_leader", "sorceress", "guard", "captive_prince"]
    },
    {
      "scene_number": 10,
      "caption": "The sorceress deciphers the runes holding the cage shut.",
      "visual_description": "Fingers tracing glowing symbols on the floor, sweat beading on her brow.",
      "characters": ["sorceress", "captive_prince", "rescue_leader"]
    },
    {
      "scene_number": 11,
      "caption": "Rumors of a dragon send panic through the tower's lower floors.",
      "visual_description": "Distant roar echoing, dust shaking from ceiling cracks, guards fleeing past.",
      "characters": ["guard", "townspeople"]
    },
    {
      "scene_number": 12,
      "caption": "The rescue party emerges onto a battlement to see the dragon circling.",
      "visual_description": "Great red shape against smoky sky, wings blotting out the sun, tail scraping spires.",
      "characters": ["rescue_leader", "sorceress", "guard", "captive_prince"]
    },
    {
      "scene_number": 13,
      "caption": "They race down a winding stairway as the dragon breathes fire above.",
      "visual_description": "Narrow spiral steps lit by orange glow, heat wave washing over them.",
      "characters": ["rescue_leader", "sorceress", "guard", "captive_prince"]
    },
    {
      "scene_number": 14,
      "caption": "A magic door blocks their path, speaking in riddles.",
      "visual_description": "Carved face in oak, eyes of amber, mouth moving slowly.",
      "characters": ["sorceress", "magic_door_face", "captive_prince"]
    },
    {
      "scene_number": 15,
      "caption": "The captive prince answers the riddle, and the door swings open.",
      "visual_description": "Door's eyes brighten, hinges creak, stone corridor beyond revealed.",
      "characters": ["captive_prince", "magic_door_face", "sorceress", "rescue_leader", "guard"]
    },
    {
      "scene_number": 16,
      "caption": "They flee across a narrow bridge spanning a deep chasm.",
      "visual_description": "Rope and plank bridge swaying, dragon silhouette looming behind, mist below.",
      "characters": ["rescue_leader", "sorceress", "guard", "captive_prince"]
    },
    {
      "scene_number": 17,
      "caption": "The guard cuts the bridge ropes to slow the dragon.",
      "visual_description": "Sword severing thick hemp, bridge lurching, dragon roaring in frustration.",
      "characters": ["guard", "dragon", "rescue_leader", "sorceress", "captive_prince"]
    },
    {
      "scene_number": 18,
      "caption": "The survivors reach the far side and watch the city fall behind.",
      "visual_description": "Silhouettes against dawn sky, ruined spires in distance, first light on their faces.",
      "characters": ["rescue_leader", "sorceress", "guard", "captive_prince"]
    }
  ]
}

